  (forall x b, wlook ws x = Some b -> exists k, cvalid k /\ caddr k <= x < caddr k + clen k /\ b = byte_of (c' k) (x - caddr k)) ->
  (forall k, cvalid k -> c' k <> a_ctx A k -> forall x, caddr k <= x < caddr k + clen k -> wlook ws x <> None) ->
  Rep (set_ctx A c') m.
